 function mutate(fn){if(d.busy())return d.toast('Termine la prise avant de modifier le rack.');try{const draft=d.normalize(d.getProject().mastering),result=fn(draft),next=d.normalize(draft);d.checkpoint();d.getProject().mastering=next;d.changed();if(typeof result==='string'){if(rackIsSplit(result)){selected=null;selectedSplit=result;}else selected=result;}d.render();return result;}catch(error){d.toast(error.message);d.render();}}
