  const old=[...root.children],insertRack=root.querySelector('.master-insert-rack'),grid=root.querySelector('.master-module-grid'),meter=root.querySelector('.master-meter-panel');
  const toolbar=document.createElement('div');toolbar.className='master-rack-toolbar';const bypass=button(state.bypass?'Rack désactivé':'Rack actif',()=>mutate(s=>{s.bypass=!s.bypass;}),'Bypass global du rack');bypass.dataset.masterBypass='';bypass.setAttribute('aria-pressed',String(state.bypass));toolbar.append(bypass);
  for(const letter of ['A','B']){const b=button(letter,()=>{if(d.busy())return;compare[compare.active]=copy(d.getProject().mastering);compare[letter]??=copy(d.getProject().mastering);const next=d.normalize(compare[letter]);d.checkpoint();d.getProject().mastering=next;compare.active=letter;d.changed();d.render();},'Comparer la configuration '+letter);b.dataset.rackCompare=letter;b.setAttribute('aria-pressed',String(compare.active===letter));toolbar.append(b);}
  toolbar.append(button('Copier '+compare.active+' → '+(compare.active==='A'?'B':'A'),()=>{compare[compare.active==='A'?'B':'A']=copy(d.getProject().mastering);d.toast('Configuration copiée pour la comparaison A/B.');}));
  for(const [value,label] of [['rack','Rack'],['macros','Macros'],['analysis','Mesures & assistant']]){const b=button(label,()=>{tab=value;if(value!=='rack')selected=null;d.render();});b.dataset.rackTab=value;b.setAttribute('aria-pressed',String(tab===value));toolbar.append(b);}
  const presetTools=document.createElement('details');presetTools.className='master-rack-presets';const summary=document.createElement('summary');summary.textContent='Presets · Charger · Sauver';presetTools.append(summary);const presetBody=document.createElement('div');presetBody.className='rack-preset-popup';presetTools.append(presetBody);toolbar.append(presetTools);
  const status=document.createElement('output');status.className='master-rack-status';status.textContent=rackLeaves(state).length+' modules · '+(Object.keys(state.splits||{}).length)+' divisions · latence de traitement estimée '+(masterRackLatency(state)*1000).toFixed(1)+' ms';
