  const board=document.createElement('div');board.className='master-rack-board';board.hidden=false;const main=document.createElement('section');main.className='master-rack-main';const title=document.createElement('h3');title.textContent='ENTRÉE → CHAÎNE → SORTIE';main.append(title,insertRack);const add=insertRack.querySelector('[data-add-insert-track]');if(add){add.textContent='+ Module';main.insertBefore(add,insertRack);}insertRack.querySelector('.master-rack-toolbar')?.remove();
  for(const [index,slot] of [...insertRack.querySelectorAll('.insert-slot')].entries()){wireSlot(slot,{index},state.inserts[index]);slot.hidden=index>=8&&!expandMain&&!state.inserts.slice(8).some(Boolean);}const more=button(expandMain?'Réduire à A–H':'Afficher I–L',()=>{expandMain=!expandMain;d.render();},'12 emplacements conservés ; vue compacte de 8 inserts comme la référence');more.className='rack-show-slots';main.append(more);
  const center=document.createElement('section');center.className='master-rack-lanes';center.hidden=tab!=='rack';const splitIds=state.inserts.filter(rackIsSplit);selectedSplit=splitIds.includes(selectedSplit)?selectedSplit:splitIds[0];
