  const mix=globalControl(state,'mix','Traité / direct',0,1,.01,true);mix.classList.add('rack-global-mix');main.append(mix);
  const bridge=document.createElement('div');bridge.className='rack-output-bridge';bridge.append(globalControl(state,'outputDb','OUT',-60,12,.1,false));
  const stereo=meter.querySelector('.master-stereo-bars');const scale=document.createElement('div');scale.className='rack-meter-scale';scale.setAttribute('aria-hidden','true');scale.innerHTML='<span>0</span><span>−12</span><span>−24</span><span>−36</span><span>−48</span><span>−60</span>';stereo.append(scale);bridge.append(stereo);
