  const bus=meter.querySelector('.master-input-gain');if(bus){bus.classList.add('rack-bus-level');const text=bus.querySelector('label');text.firstChild.textContent='NIVEAU DU BUS MASTER · AVANT RACK ';}meter.classList.add('rack-analysis-meters');analysis.append(meter);
  const macroPanel=document.createElement('section');macroPanel.className='master-rack-macros';macroPanel.hidden=tab!=='macros';renderMacros(macroPanel,state);
