 return {open,close,selectedModule:()=>selected,isOpen:()=>!!panel&&!panel.hidden,decorate,mutate,openModule,chooseSplit,meters,select:id=>{selected=id;selectedSplit=rackIsSplit(id)?id:selectedSplit;}};
